package com.horabase.api.incident;
import com.horabase.api.incident.dto.*; import jakarta.validation.Valid; import org.springframework.http.HttpStatus; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.time.LocalDate; import java.util.*;
@RestController @RequestMapping("/api/businesses/{businessId}/incidents") @PreAuthorize("@businessSecurity.canAccess(authentication, #businessId)")
public class AttendanceIncidentController{private final AttendanceIncidentService service;public AttendanceIncidentController(AttendanceIncidentService s){service=s;}@PostMapping @ResponseStatus(HttpStatus.CREATED) public IncidentResponse create(@PathVariable Long businessId,@Valid @RequestBody IncidentRequest q){return service.create(businessId,q);}@GetMapping public List<IncidentResponse> list(@PathVariable Long businessId,@RequestParam LocalDate from,@RequestParam LocalDate to,@RequestParam(required=false)Long employeeId){return service.list(businessId,from,to,employeeId);}@PostMapping("/{id}/resolve")public IncidentResponse resolve(@PathVariable Long businessId,@PathVariable Long id,@Valid @RequestBody ResolveIncidentRequest q){return service.resolve(businessId,id,q);}}
